const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
    // 1. Geometry & Time Definitions
    const gerdPoint = ee.Geometry.Point([35.1887, 11.2126]); // GERD coordinates
    const roi = gerdPoint.buffer(20000); // 20km buffer around GERD

    const sep2021 = ['2021-09-01', '2021-10-01'];
    const feb2022 = ['2022-02-01', '2022-03-01'];

    // 2. Data Acquisition - Sentinel-2 for water detection
    function getS2Collection(dateRange) {
        return ee.ImageCollection('COPERNICUS/S2_SR_HARMONIZED')
            .filterBounds(roi)
            .filterDate(dateRange[0], dateRange[1])
            .filter(ee.Filter.lt('CLOUDY_PIXEL_PERCENTAGE', 30))
            .map(function(image) {
                return image.clip(roi);
            });
    }

    // 3. Water detection using NDWI
    function addNDWI(image) {
        const ndwi = image.normalizedDifference(['B3', 'B8']).rename('NDWI');
        return image.addBands(ndwi);
    }

    // 4. Get collections and check size
    const sepCol = getS2Collection(sep2021).map(addNDWI);
    const febCol = getS2Collection(feb2022).map(addNDWI);

    const sepSize = sepCol.size().getInfo();
    const febSize = febCol.size().getInfo();

    print(`Sep 2021 Images: ${sepSize}, Feb 2022 Images: ${febSize}`);

    // Handle empty collections
    if (sepSize === 0 || febSize === 0) {
        print("Empty collection detected - trying Landsat 8/9");

        // Fallback to Landsat
        function getLandsatCollection(dateRange) {
            const ls8 = ee.ImageCollection('LANDSAT/LC08/C02/T1_L2')
                .filterBounds(roi)
                .filterDate(dateRange[0], dateRange[1]);
            const ls9 = ee.ImageCollection('LANDSAT/LC09/C02/T1_L2')
                .filterBounds(roi)
                .filterDate(dateRange[0], dateRange[1]);
            return ls8.merge(ls9).map(function(image) {
                const ndwi = image.normalizedDifference(['SR_B3', 'SR_B5']).rename('NDWI');
                return image.addBands(ndwi).clip(roi);
            });
        }

        const sepColL = getLandsatCollection(sep2021);
        const febColL = getLandsatCollection(feb2022);
        const sepSizeL = sepColL.size().getInfo();
        const febSizeL = febColL.size().getInfo();

        print(`Landsat Sep 2021: ${sepSizeL}, Feb 2022: ${febSizeL}`);

        if (sepSizeL === 0 || febSizeL === 0) {
            print("<answer>C1</answer>");
            return;
        }

        var sepImg = sepColL.median().select('NDWI');
        var febImg = febColL.median().select('NDWI');
    } else {
        var sepImg = sepCol.median().select('NDWI');
        var febImg = febCol.median().select('NDWI');
    }

    // 5. Compute water areas (NDWI > 0 threshold)
    const waterThreshold = 0.0;

    const sepWater = sepImg.gt(waterThreshold);
    const febWater = febImg.gt(waterThreshold);

    const sepStats = sepWater.reduceRegion({
        reducer: ee.Reducer.sum(),
        geometry: roi,
        scale: 1000,
        maxPixels: 1e9
    });

    const febStats = febWater.reduceRegion({
        reducer: ee.Reducer.sum(),
        geometry: roi,
        scale: 1000,
        maxPixels: 1e9
    });

    const sepPixels = sepStats.get('NDWI').getInfo();
    const febPixels = febStats.get('NDWI').getInfo();

    print(`Sep 2021 water pixels: ${sepPixels}`);
    print(`Feb 2022 water pixels: ${febPixels}`);

    // 6. Check for valid pixels
    if (sepPixels === 0 || febPixels === 0) {
        print("<answer>C2</answer>");
        return;
    }

    // 7. Calculate change
    const changePercent = ((febPixels - sepPixels) / sepPixels) * 100;

    // 8. Validation and output
    if (changePercent === null || changePercent === undefined || 
        Math.abs(changePercent) > 10000 || isNaN(changePercent)) {
        print("<answer>C3</answer>");
        return;
    }

    print(`Water change: ${changePercent.toFixed(1)}%`);

    if (changePercent < 0) {
        print("<answer>A</answer>");  // Yes, decreased
    } else {
        print("<answer>B</answer>");  // No, didn't decrease
    }
}

async function initEE() {
    await new Promise((resolve, reject) => {
        ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
    });
    await new Promise((resolve, reject) => {
        ee.initialize(null, null, resolve, reject);
    });
    await runAnalysis();
}

initEE();
